import React from 'react';

import {
  finishIv,
  getInterviewById,
  getIvStartData,
  getQuestions,
} from '@apps/Interview/@services/interview.service';
import { IInterview, IQuestion, IQuestionType } from '@apps/Interview/@types/interview.types';
import { IIvPrepareDTO } from '@apps/Interview/@types/interview.types.dto';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

import QuestionForAnswer from '../QuestionForAnswer';

interface IInterviewRunProps {
  id_interview: number;
  onComplete?: () => void;
}

const InterviewRun: React.FC<IInterviewRunProps> = ({ id_interview, onComplete }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IInterview>();
  const [startData, setStartData] = React.useState<IIvPrepareDTO>();
  const [questions, setQuestions] = React.useState<IQuestion[]>([]);

  const [isStarted, setIsStarted] = React.useState(false);
  const [isFinished, setIsFinished] = React.useState(false);

  const formRef = React.useRef<HTMLFormElement>(null);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);

      const res0 = await getIvStartData(id_interview);
      setStartData(res0);

      if (res0.ok?.i_finish) {
        setIsFinished(true);
      } else if (res0.bad?.length > 0) {
        throw new Error(res0.bad.join('; '));
      }

      const res = await getInterviewById(id_interview);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_interview]);

  React.useEffect(() => {
    load();
  }, [load]);

  React.useEffect(() => {
    if (!isStarted) return;
    const run = async () => {
      try {
        setIsLoading(true);
        const res1 = await getQuestions(id_interview);
        setQuestions(res1);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };
    run();
  }, [isStarted, id_interview]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (startData && startData.bad && startData.bad.length > 0)
    return (
      <PohAlert variant={AlertVariant.Danger}>
        {startData.bad.map((x) => {
          return <li key={x}>{x}</li>;
        })}
      </PohAlert>
    );
  if (!data)
    return <PohAlert variant={AlertVariant.Danger}>Has no interview {id_interview}</PohAlert>;

  if (!isStarted)
    return (
      <div>
        <div dangerouslySetInnerHTML={{ __html: data.hello_text }} />
        <PohButton
          size={ButtonSize.Big}
          variant={ButtonVariant.OutlineSuccess}
          className="mt-4"
          onClick={() => setIsStarted(true)}
          block
        >
          Начать
        </PohButton>
      </div>
    );
  if (isFinished) return <div dangerouslySetInnerHTML={{ __html: data.by_text }} />;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const dataForSave: Record<number, any> = {};
    questions.forEach((x) => {
      if (!formRef.current) return;

      const el = formRef.current.querySelector(`[name='${x.id}']`) as HTMLInputElement;
      dataForSave[x.id] = {
        v_from_input: x.type === IQuestionType.Input && el.value ? el.value : null,
        v_from_variants:
          x.type === IQuestionType.Select
            ? Array.from(formRef.current.querySelectorAll(`[name='${x.id}']:checked`)).map(
                (ee: any) => parseInt((ee as HTMLElement).dataset.value ?? ''),
              )
            : null,
        v_from_dir: null,
        v_custom:
          (formRef.current.querySelector(`[name='${x.id}-custom']`) as HTMLInputElement)?.value ??
          null,
      };
    });

    await finishIv(dataForSave);
    onComplete?.();
    setIsFinished(true);
  };

  return (
    <form onSubmit={handleSubmit} ref={formRef}>
      {questions.map((q) => {
        return <QuestionForAnswer key={q.id} item={q} />;
      })}
      <PohRow className="mt-3">
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton block size={ButtonSize.Big} variant={ButtonVariant.Primary} type="submit">
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export default InterviewRun;

export const runInterviewInModal = (id: number, title?: string, callback?: () => void) => {
  showModal({
    title,
    children: (clos) => {
      return (
        <div style={{ minWidth: '80vw', minHeight: '70vh' }}>
          <InterviewRun
            id_interview={id}
            onComplete={() => {
              clos();
              callback?.();
            }}
          />
        </div>
      );
    },
  });
};
